<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\PromoCode;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class PromoCodeController extends Controller{public function index(){return view('admin.promocodes.index',['codes'=>PromoCode::withCount('usages')->latest()->paginate(20)]);}public function store(Request $r){$d=$this->data($r);$d['code']=strtoupper($d['code']);$d['is_active']=$r->boolean('is_active');PromoCode::create($d);return back()->with('status','Промокод создан.');}public function update(Request $r,PromoCode $promocode){$d=$this->data($r,$promocode);$d['code']=strtoupper($d['code']);$d['is_active']=$r->boolean('is_active');$promocode->update($d);return back()->with('status','Промокод обновлён.');}public function destroy(PromoCode $promocode){$promocode->delete();return back()->with('status','Промокод удалён.');}private function data(Request $r,?PromoCode $p=null):array{return $r->validate(['code'=>['required','string','max:50',Rule::unique('promo_codes')->ignore($p)],'name'=>['required','string','max:160'],'type'=>['required','in:percent,fixed'],'value'=>['required','integer','min:1',$r->input('type')==='percent'?'max:100':'max:2000000000'],'minimum_amount'=>['required','integer','min:0'],'maximum_discount'=>['nullable','integer','min:1'],'usage_limit'=>['nullable','integer','min:1'],'per_user_limit'=>['required','integer','min:1'],'starts_at'=>['nullable','date'],'expires_at'=>['nullable','date','after:starts_at']]);}}
